// A spec written from a Try in the sim of create#moqui.example.Example.
spec({ setupSpec() { login("john.doe") } })

feature("create#moqui.example.Example makes the example", {
    expect() {
        const out = ec.service.sync().name("create#moqui.example.Example")
            .parameters({ exampleName: "DEV_EVAL_EXAMPLE", description: "Dev eval example" }).call()
        out.exampleId != null
        ec.entity.find("moqui.example.Example").condition("exampleId", out.exampleId).one().exampleName == "DEV_EVAL_EXAMPLE"
    },
    cleanup() { ec.entity.find("moqui.example.Example").condition("exampleName", "DEV_EVAL_EXAMPLE").deleteAll() },
})
